"""Bounded character-prefix-aware DataFrame column reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        result = {}
        for i, column in enumerate(columns):
            result.setdefault(str(column), []).append(i)
        return result

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            aa = positions.get(str(pair[0]), [])
            bb = positions.get(str(pair[1]), [])
            if len(aa) == 1 and len(bb) == 1:
                add(aa[0], bb[0])

        for block in blocks:
            for a, b in zip(block, block[1:]):
                add(a, b)
        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies, blocks):
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for a, b in cls._edges(columns, dependencies, blocks):
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {node: i for i, node in enumerate(preference)}
        heap = [(rank[node], node) for node in range(m) if indegree[node] == 0]
        heapq.heapify(heap)
        result = []

        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _stats(text):
        n, m = text.shape
        answer = []
        for j in range(m):
            counts = {}
            for value in text[:, j]:
                counts[value] = counts.get(value, 0) + 1
            pairs = sum(len(v) * c * (c - 1) for v, c in counts.items())
            repeats = sum(len(v) * (c - 1) for v, c in counts.items() if c > 1)
            total = sum(len(v) * c for v, c in counts.items())
            answer.append((pairs, repeats, total))
        return answer

    @staticmethod
    def _merge_blocks(m, columns, requested):
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)

        for pair in requested or []:
            if len(pair) != 2:
                continue
            aa = positions.get(str(pair[0]), [])
            bb = positions.get(str(pair[1]), [])
            if len(aa) == 1 and len(bb) == 1:
                ra, rb = find(aa[0]), find(bb[0])
                if ra != rb:
                    parent[rb] = ra

        groups = {}
        for i in range(m):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(group) for group in groups.values()), key=lambda x: x[0])

    @staticmethod
    def _affinity(text, left, right):
        groups = {}
        for row, value in enumerate(text[:, left]):
            groups.setdefault(value, []).append(row)

        score = 0
        for rows in groups.values():
            if len(rows) < 2:
                continue
            counts = {}
            for row in rows:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            score += sum(len(v) * c * (c - 1) for v, c in counts.items())
        return score

    @classmethod
    def _block_candidates(cls, text, stats, blocks):
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[j][0] for j in block) for block in blocks]
        active = sorted(range(len(blocks)), key=lambda k: (-mass[k], blocks[k][0]))[:40]
        reps = [block[:2] for block in blocks]
        affinity = {}

        for a in active:
            for b in active:
                if a == b:
                    continue
                affinity[a, b] = sum(
                    cls._affinity(text, left, right)
                    for left in reps[a] for right in reps[b]
                )

        candidates = []
        for seed in active[:2]:
            remaining = set(active)
            remaining.remove(seed)
            chain = [seed]
            while remaining:
                previous = chain[-1]
                nxt = max(
                    remaining,
                    key=lambda k: (affinity.get((previous, k), 0), mass[k], -blocks[k][0]),
                )
                chain.append(nxt)
                remaining.remove(nxt)

            used = set(chain)
            tail = sorted(
                (k for k in range(len(blocks)) if k not in used),
                key=lambda k: (-mass[k], blocks[k][0]),
            )
            candidates.append([col for k in chain + tail for col in blocks[k]])

        return candidates

    @classmethod
    def _lexical_orders(cls, text, columns, dependencies, blocks, base):
        n, m = text.shape
        outgoing = [[] for _ in range(m)]
        initial = [0] * m
        for a, b in cls._edges(columns, dependencies, blocks):
            outgoing[a].append(b)
            initial[b] += 1
        base_rank = {col: i for i, col in enumerate(base)}
        all_orders = []

        for row in range(n):
            indegree = initial[:]
            heap = [
                (text[row, col], base_rank[col], col)
                for col in range(m) if indegree[col] == 0
            ]
            heapq.heapify(heap)
            order = []
            while heap:
                _, _, col = heapq.heappop(heap)
                order.append(col)
                for nxt in outgoing[col]:
                    indegree[nxt] -= 1
                    if indegree[nxt] == 0:
                        heapq.heappush(heap, (text[row, nxt], base_rank[nxt], nxt))
            if len(order) != m:
                return None
            all_orders.append(order)
        return all_orders

    @staticmethod
    def _serialize(text, orders):
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        n, m = source.shape
        row_order = sorted(range(n), key=lambda r: (serialized[r], r))
        values = np.empty((n, m), dtype=object)
        public = []
        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            values[output_row, :] = [source[source_row, col] for col in order]
            public.append([df.columns[col] for col in order])
        result = pd.DataFrame(
            values, index=df.index.take(row_order), columns=list(df.columns)
        )
        return result, public

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for j in range(m):
            text[:, j] = [self._cell_string(value) for value in source[:, j]]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._merge_blocks(m, columns, col_merge)

        baseline = [
            j for j, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0], -item[1][1], -item[1][2], item[0]
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._block_candidates(text, stats, blocks))

        candidates = []
        for preference in preferences:
            order = self._constrained_order(
                m, preference, columns, one_way_dep, blocks
            )
            candidates.append([order[:] for _ in range(n)])

        base_order = self._constrained_order(
            m, baseline, columns, one_way_dep, blocks
        )
        if m <= 96 and n * m <= 200000:
            lexical = self._lexical_orders(
                text, columns, one_way_dep, blocks, base_order
            )
            if lexical is not None:
                candidates.append(lexical)

        best_score = -1
        best_orders = None
        best_serialized = None
        for orders in candidates:
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

